{
  "description": "The creature is a quadrupedal animal shown in right-facing profile with the head, fur, and paws of a brown bear integrated with a glossy black segmented exoskeleton that covers the back, sides, neck, and legs. A single large, curved, shiny black horn with two small inner points and a segmented base rises from the middle of the forehead and arches backward over the shoulders. The body is encased in overlapping hard plates with rows of oval openings along the flanks, tapering to a short pointed armored tail at the rear, while brown fur and claws remain visible on the face, ears, and feet.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a lighter tan muzzle, a black nose, small brown eyes, and a slightly open mouth showing the lower lip",
      "where": "at the front right end of the body, in front of the armored neck"
    },
    {
      "part": "horns",
      "looks_like": "a single large glossy black horn with a thick segmented base on the forehead, curving up and backward with two sharp triangular projections on its inner curve and a pointed tip",
      "where": "centered on top of the head between the ears, extending upward and backward over the back"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in brown fur, with slightly darker edges",
      "where": "on top of the head on either side of the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs encased in glossy black overlapping segmented armor plates, with folds of brown fur visible at the joints just above the paws",
      "where": "underneath the body, two in front and two in back supporting the torso"
    },
    {
      "part": "feet",
      "looks_like": "four broad brown furry paws with five long curved light-tan claws on each, with dense fur on the top and pads underneath",
      "where": "at the bottom ends of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short tapered tail covered in small overlapping glossy black plates ending in a pointed tip",
      "where": "at the extreme rear left of the body, extending backward from the armored back"
    },
    {
      "part": "plates",
      "looks_like": "glossy black overlapping armor plates forming segmented bands across the back, sides, neck, and upper legs, with a row of small oval holes along the lower side of the back plates and larger oval holes along the neck and flank",
      "where": "covering the dorsal back from behind the head to the tail, wrapping around the sides, neck, and most of each leg"
    },
    {
      "part": "shell",
      "looks_like": "a continuous hard domed carapace of shiny black plates with distinct transverse segments and a smooth reflective surface",
      "where": "over the entire torso forming the main body covering from the shoulders to the hips"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle",
    "woodlouse"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
